/**
 * axil generate client [--from <url|file>] [--out <file>] [--name <Class>]
 *
 * Reads an OpenAPI 3.x JSON document (an http(s) URL, fetched with a 10 s
 * timeout, or a local file) and writes one dependency-free TypeScript client
 * (see generators/openapi-client.ts).
 *
 *   --from   default http://localhost:<PORT from .env, else 3000>/openapi.json
 *   --out    default src/api-client.ts
 *   --name   default ApiClient (factory: createApiClient)
 *
 * An existing --out file is replaced only when it was generated by axil, or
 * with --force.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs'
import { dirname, isAbsolute, relative, resolve } from 'path'

import { generateClientSource, isGeneratedClient, OpenApiDocument } from '../generators/openapi-client'
import * as ui from '../ui'
import { readAppPort } from './run'

export interface GenerateClientOptions {
  // OpenAPI document: http(s) URL or file path (default: http://localhost:<PORT>/openapi.json)
  from?:    string
  // Output file, relative to cwd (default: src/api-client.ts)
  out?:     string
  // Client class name (default: ApiClient)
  name?:    string
  // Overwrite an --out file that was not generated by axil
  force?:   boolean
  // Project directory (default: process.cwd())
  cwd?:     string
  // Fetch timeout in ms (default: 10000)
  timeout?: number
  // Fixed header timestamp (tests)
  timestamp?: string | false
  // Suppress console output
  silent?:  boolean
}

export interface GenerateClientResult {
  file:       string
  source:     string
  operations: string[]
  schemas:    string[]
  warnings:   string[]
}

export const DEFAULT_CLIENT_OUT = 'src/api-client.ts'

/** Fetch or read the document and parse it as JSON. */
export async function loadOpenApiDocument(from: string, cwd: string, timeoutMs = 10000): Promise<OpenApiDocument> {
  let text: string

  if (/^https?:\/\//i.test(from)) {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), timeoutMs)
    try {
      const res = await fetch(from, { headers: { accept: 'application/json' }, signal: controller.signal })
      if (!res.ok) throw new Error(`GET ${from} answered ${res.status} ${res.statusText}`.trim())
      text = await res.text()
    } catch (error) {
      if ((error as Error)?.name === 'AbortError') {
        throw new Error(`Timed out after ${Math.round(timeoutMs / 1000)}s fetching ${from}`)
      }
      const cause = (error as any)?.cause?.code || (error as any)?.cause?.message
      throw new Error(
        `Could not fetch ${from}: ${(error as Error)?.message ?? String(error)}${cause ? ` (${cause})` : ''}. ` +
        'Is the app running? Pass --from <url|file> to use another document.'
      )
    } finally {
      clearTimeout(timer)
    }
  } else {
    const file = isAbsolute(from) ? from : resolve(cwd, from)
    if (!existsSync(file)) throw new Error(`OpenAPI document not found: ${file}`)
    text = readFileSync(file, 'utf8')
  }

  try {
    return JSON.parse(text.replace(/^﻿/, '')) as OpenApiDocument
  } catch (error) {
    const yaml = /^\s*(openapi|swagger)\s*:/m.test(text)
    throw new Error(
      yaml
        ? `${from} looks like YAML; only JSON documents are supported. Convert it to JSON first.`
        : `${from} is not valid JSON: ${(error as Error).message}`
    )
  }
}

export async function generateClient(opts: GenerateClientOptions = {}): Promise<GenerateClientResult> {
  const started = Date.now()
  const cwd     = opts.cwd || process.cwd()
  const quiet   = opts.silent === true
  const from    = opts.from || `http://localhost:${readAppPort(cwd)}/openapi.json`
  const outRel  = opts.out || DEFAULT_CLIENT_OUT
  const outAbs  = isAbsolute(outRel) ? outRel : resolve(cwd, outRel)

  if (!quiet) {
    ui.title('generate', 'client')
    ui.keyValue([
      ['Source', /^https?:/i.test(from) ? ui.cmd(from) : ui.path(from)],
      ['Output', ui.path(shortPath(cwd, outAbs))]
    ])
    ui.line()
  }

  const spin = quiet ? null : ui.spinner(`Reading ${from}`)
  let document: OpenApiDocument
  try {
    document = await loadOpenApiDocument(from, cwd, opts.timeout ?? 10000)
  } catch (error) {
    spin?.fail('Could not read the OpenAPI document')
    throw error
  }
  spin?.succeed('OpenAPI document loaded', [document.info?.title, document.openapi && `OpenAPI ${document.openapi}`].filter(Boolean).join(', '))

  const generated = generateClientSource(document, {
    name:      opts.name,
    source:    from,
    timestamp: opts.timestamp
  })

  if (existsSync(outAbs) && !opts.force && !isGeneratedClient(readFileSync(outAbs, 'utf8'))) {
    throw new Error(
      `${shortPath(cwd, outAbs)} exists and was not generated by axil. ` +
      'Pass --force to overwrite it, or choose another file with --out.'
    )
  }

  mkdirSync(dirname(outAbs), { recursive: true })
  writeFileSync(outAbs, generated.code, 'utf8')

  const result: GenerateClientResult = {
    file:       outAbs,
    source:     from,
    operations: generated.operations,
    schemas:    generated.schemas,
    warnings:   generated.warnings
  }
  if (quiet) return result

  for (const w of generated.warnings) ui.warn(w)
  ui.success(`Wrote ${shortPath(cwd, outAbs)}`, `${plural(generated.operations.length, 'operation')}, ${plural(generated.schemas.length, 'schema')}`)

  const name = opts.name ?? 'ApiClient'
  const fromSrc = relative(resolve(cwd, 'src'), outAbs).replace(/\\/g, '/').replace(/\.ts$/, '.js')
  const importPath = fromSrc.startsWith('.') ? fromSrc : `./${fromSrc}`
  ui.section('Use it:')
  ui.line(`  ${ui.cmd(`import { create${name}, ApiError } from '${importPath}'`)}`)
  ui.line(`  ${ui.cmd(`const api = create${name}({ baseUrl: 'http://localhost:3000', token })`)}`)
  ui.done('Client generated', started)
  return result
}

function plural(n: number, word: string): string {
  return `${n} ${word}${n === 1 ? '' : 's'}`
}

function shortPath(cwd: string, target: string): string {
  const rel = relative(cwd, target)
  return rel && !rel.startsWith('..') && !isAbsolute(rel) ? rel : target
}
